        proAudioCableLoom: { label: "Inventario de loom de cables (XLR / TRS / digital)", hint: "Cuenta cada cable — XLR, TRS, USB-C, Thunderbolt, ADAT, alimentación. Congelado en la reserva; contado en la entrega.", placeholder: "2× XLR 3 m, 2× TRS 2 m, 1× USB-C 1 m, IEC..." },
        proAudioGearType: { label: "Tipo de equipo pro audio", hint: "Interface vs mixer vs mic vs monitor — no un stack PA en vivo (eso es Music → PA Systems)." },
        projectorInputInventory: { label: "Inventario HDMI / entradas", hint: "Lista cada puerto y cable/adaptador incluido — HDMI, VGA, USB-C, stick inalámbrico, audio out.", placeholder: "2× HDMI in, 1× VGA, audio 3.5mm; incluye HDMI 6ft + adaptador VGA..." },
        projectorLampHoursNotes: { label: "Horas de lámpara / vida", hint: "En unidades de lámpara: horas usadas o restantes si se conocen. Nota honesta — no reclamación de garantía.", placeholder: "Lámpara ~1200h usadas / ~2000h rating; preferir modo dim..." },
        projectorLightSource: { label: "Fuente de luz", hint: "Lámpara, láser o LED — afecta calentamiento, uso outdoor y riesgo de recambio." },
        projectorLumenBand: { label: "Brillo (franja de lúmenes)", hint: "Lúmenes ANSI / de marketing aproximados. Salas pequeñas necesitan menos; salones claros más. Franja suave — no certificado de lab." },
        projectorNativeResBand: { label: "Resolución nativa", hint: "Resolución nativa del panel (no el máximo soportado). Define nitidez esperada." },
        projectorPowerCableLengthBand: { label: "Largo del cable de corriente", hint: "Largo del cable incluido o extensión. Evita sorpresas de distancia al enchufe en venues." },
        projectorScreenStandIncluded: { label: "¿Pantalla / soporte incluidos?", hint: "Aclara si va pantalla de proyección o trípode/soporte con la unidad." },
        projectorThrowNotes: { label: "Throw / distancia", hint: "Short-throw vs estándar, distancia típica para un tamaño de imagen, techo vs mesa.", placeholder: "Short-throw ~3–5ft para 100in; mesa OK; sin lens shift..." },
        projectorUseEnv: { label: "Uso interior / exterior", hint: "Polvo, rocío y sol directo dañan la óptica — define la regla antes de reservar." },
        rackMountIncluded: { label: "Kit rack / mount", hint: "Si incluye orejas rack, wall plate, pole mount, o solo desktop." },
        rackMountKitIncluded: { label: "Rieles / kit de montaje", hint: "Indica si van rieles deslizantes, cage nuts o cable arm. Usa not-rack para towers y laptop WS." },
        ramCapacityBand: { label: "Banda de RAM", hint: "Banda suave para planificar — no medición de laboratorio." },
        remoteMgmtAccessPolicy: { label: "Acceso IPMI / iDRAC / iLO", hint: "BMC abierto genera disputas de seguridad — define credenciales, solo lectura, deshabilitado o sin acceso." },
        renterFactoryRestorePolicy: { label: "Restore de fábrica al devolver", hint: "Si el inquilino debe restaurar fábrica antes de devolver, el anfitrión después, o leave-config OK (anfitrión limpia)." },
        resolutionHdrBand: { label: "Resolución / HDR", hint: "Resolución nativa y sabor HDR que debe usar el inquilino — SDR vs HDR10 / HLG / mapa LED mixto." },
        returnFunctionTestAttest: { label: "Política de prueba funcional", hint: "Power-on / smoke-test I/O del anfitrión al listar o entregar; el inquilino debe devolver con la misma prueba." },
        returnFunctionTestPolicy: { label: "Test de función al devolver", hint: "Cómo se verifican puertos/preview/stream antes de liberar el depósito." },
        returnWipeAckDepth: { label: "Profundidad de acuse de wipe al devolver", hint: "Quién resetea o cierra sesión al devolver — completa el bucle de privacidad con el wipe del anfitrión." },
        sampleRateBitDepthBand: { label: "Sample-rate / bit-depth máx. (suave)", hint: "Recomendado en interfaces/mixers/grabadoras digitales. Banda suave — no certificado de laboratorio." },
        serverFormFactor: { label: "Factor de forma", hint: "Tower vs rack U vs laptop / AIO workstation — define escritorio vs colo vs WS móvil." },
        serverPowerConfig: { label: "Energía / PSU", hint: "120V vs 240V, PSU simple vs dual redundante, o PDU C13/C14. Ficha suave — no socio eléctrico." },
        shippingWeightNotes: { label: "Notas de envío / peso", hint: "Opcional: peso aprox., solo recogida local, dos personas, freight.", placeholder: "~25 kg 2U; solo recogida local; se recomienda dos personas..." },
        smartDeviceClass: { label: "Clase de dispositivo", hint: "Altavoz/pantalla, cámara, timbre, termostato, cerradura, iluminación, hub, sensores o kit multi-dispositivo." },
        smartPowerType: { label: "Tipo de alimentación", hint: "Enchufe, batería, hardwired, USB, PoE o kit mixto — define riesgo de instalación y estado de devolución." },
        smartProtocolBand: { label: "Banda de protocolos", hint: "Marca cada radio / stack — Wi-Fi, Thread, Zigbee, Matter, Bluetooth, Z-Wave o nube propietaria." },
        speakerFormBand: { label: "Forma del altavoz", hint: "Consumer/portable — Bluetooth portable, wired bookshelf, party boombox, soundbar o smart. No PA de escenario." },
        speakerPowerBand: { label: "Fuente de energía", hint: "Solo batería, AC de red, híbrido batería+AC, o USB — congela picnic vs enchufe." },
        speakerWeatherBand: { label: "Clasificación exterior / clima", hint: "Solo interior vs splash-OK vs outdoor-rated — piscina y patio generan reclamos por agua." },
        standMountIncluded: { label: "¿Soporte / montaje incluido?", hint: "Si incluye soporte de pie, mástil o soporte de pared. Si sí, marca también stand_mount en el inventario." },
        stereoPairNotes: { label: "Notas de emparejamiento / estéreo", hint: "Opcional: emparejamiento TWS, estéreo L/R, o segunda unidad no incluida.", placeholder: "PartyBoost / TWS con modelo compatible OK; este anuncio es una sola unidad; no incluye segundo altavoz..." },
        transportFragilityBand: { label: "Fragilidad de transporte", hint: "Paneles de cristal vs LED modular vs flight-case rugged — define embalaje y reclamaciones." },
        videoIoInventory: { label: "Inventario SDI / HDMI I/O", hint: "Puertos del equipo más cables/convertidores incluidos. Ficha de patch suave.", placeholder: "4× HDMI in, 1× HDMI out, 1× SDI out; 3× HDMI + convertidor SDI↔HDMI…" },
        vrHeadsetHygieneNotes: { label: "Notas de higiene del headset VR", hint: "Foam facial, reglas de limpieza, contacto con piel. Ficha suave — no promo de café.", placeholder: "Limpiar foam con toallita sin alcohol antes de devolver; sin maquillaje en el sello..." },
